/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk=0, rst_n=0, data=0;
  wire match, not_match;
  TopModule dut(.clk(clk), .rst_n(rst_n), .data(data), .match(match), .not_match(not_match));
  always #5 clk = ~clk;

  task drive_bit(input reg b);
    begin
      data = b;
      #9;
      "'$display("t=%0t data=%0b pstate? match=%0b not_match=%0b", $time, data, match, not_match);
      #1;
    end
  endtask

  initial begin
    $dumpfile("tb.vcd"); $dumpvars(0,tb);
    #2; rst_n=0; data=0;
    #8; rst_n=1;
    // matching group 011100
    drive_bit(0); drive_bit(1); drive_bit(1); drive_bit(1); drive_bit(0); drive_bit(0);
    // failing group starting with 0 but wrong later: 011101
    drive_bit(0); drive_bit(1); drive_bit(1); drive_bit(1); drive_bit(0); drive_bit(1);
    // failing group starting with 1 should skip group
    drive_bit(1); drive_bit(0); drive_bit(0); drive_bit(0); drive_bit(0); drive_bit(0);
    #10; $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

